class Solution {
    public boolean isAlienSorted(String[] words, String order) {
        int[] rank = new int[26];
        for (int i = 0; i < order.length(); i++) {
            rank[order.charAt(i) - 'a'] = i;
        }
        for (int i = 0; i + 1 < words.length; i++) {
            if (compare(words[i], words[i + 1], rank) > 0) {
                return false;
            }
        }
        return true;
    }

    private int compare(String left, String right, int[] rank) {
        int limit = Math.min(left.length(), right.length());
        for (int i = 0; i < limit; i++) {
            int a = rank[left.charAt(i) - 'a'];
            int b = rank[right.charAt(i) - 'a'];
            if (a != b) {
                return a - b;
            }
        }
        return left.length() - right.length();
    }
}

class Solution {
    public boolean isAlienSorted(String[] words, String order) {
        char[] canonical = new char[26];
        for (int i = 0; i < order.length(); i++) {
            canonical[order.charAt(i) - 'a'] = (char) ('a' + i);
        }

        String previous = translate(words[0], canonical);
        for (int i = 1; i < words.length; i++) {
            String current = translate(words[i], canonical);
            if (previous.compareTo(current) > 0) {
                return false;
            }
            previous = current;
        }
        return true;
    }

    private String translate(String word, char[] canonical) {
        char[] converted = new char[word.length()];
        for (int i = 0; i < word.length(); i++) {
            converted[i] = canonical[word.charAt(i) - 'a'];
        }
        return new String(converted);
    }
}

import java.util.Arrays;

class Solution {
    public boolean isAlienSorted(String[] words, String order) {
        int[] rank = new int[26];
        for (int i = 0; i < order.length(); i++) {
            rank[order.charAt(i) - 'a'] = i;
        }

        String[] sorted = words.clone();
        Arrays.sort(sorted, (a, b) -> compareAlien(a, b, rank));
        for (int i = 0; i < words.length; i++) {
            if (!words[i].equals(sorted[i])) {
                return false;
            }
        }
        return true;
    }

    private int compareAlien(String a, String b, int[] rank) {
        int limit = Math.min(a.length(), b.length());
        for (int i = 0; i < limit; i++) {
            int left = rank[a.charAt(i) - 'a'];
            int right = rank[b.charAt(i) - 'a'];
            if (left != right) {
                return left - right;
            }
        }
        return a.length() - b.length();
    }
}

class Solution {
    public boolean isAlienSorted(String[] words, String order) {
        int[] rank = new int[26];
        for (int i = 0; i < order.length(); i++) {
            rank[order.charAt(i) - 'a'] = i;
        }
        for (int i = 0; i + 1 < words.length; i++) {
            if (!inOrder(words[i], words[i + 1], 0, rank)) {
                return false;
            }
        }
        return true;
    }

    private boolean inOrder(String left, String right, int index, int[] rank) {
        if (index == left.length() || index == right.length()) {
            return left.length() <= right.length();
        }
        int a = rank[left.charAt(index) - 'a'];
        int b = rank[right.charAt(index) - 'a'];
        if (a != b) {
            return a < b;
        }
        return inOrder(left, right, index + 1, rank);
    }
}

class Solution {
    public boolean isAlienSorted(String[] words, String order) {
        int[] rank = new int[26];
        for (int i = 0; i < order.length(); i++) {
            rank[order.charAt(i) - 'a'] = i + 1;
        }

        int[] previous = encode(words[0], rank);
        for (int i = 1; i < words.length; i++) {
            int[] current = encode(words[i], rank);
            if (!lessOrEqual(previous, current)) {
                return false;
            }
            previous = current;
        }
        return true;
    }

    private int[] encode(String word, int[] rank) {
        int[] encoded = new int[word.length() + 1];
        for (int i = 0; i < word.length(); i++) {
            encoded[i] = rank[word.charAt(i) - 'a'];
        }
        encoded[word.length()] = 0;
        return encoded;
    }

    private boolean lessOrEqual(int[] left, int[] right) {
        int limit = Math.min(left.length, right.length);
        for (int i = 0; i < limit; i++) {
            if (left[i] != right[i]) {
                return left[i] < right[i];
            }
        }
        return true;
    }
}
